script:
// SegmentedTabs (ds-metrics §17 — accentPill / flatPill): 48pt track, inset 4, gap 4, radius 24 (no token), bg2.
// Segments share the width equally; the selected one is an accentPrimary pill (radius 20 = 24 − inset) with onAccent
// text, the others el9; cross-fade with @motion.smooth (DS accentPill: spring 0.3 s). Controlled:
//   {"type": "SegmentedTabs", "props": {"items": "=tabs", "selected": "=tab"}, "on": {"change": "tab = event.index"}}
// `change` fires only for a segment that is not already selected.
param items: list<string>
param selected: number = 0
event change(index: number)

on.tap:
if i != selected {
  haptic("selection")
  emit change({index: i})
}
